CREATE TABLE IF NOT EXISTS governed_claims(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,claim_ref TEXT NOT NULL,policy_ref TEXT NOT NULL,coverage_rule_version TEXT NOT NULL,jurisdiction TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'fnol',evidence JSONB NOT NULL DEFAULT '[]'::jsonb,estimate NUMERIC(14,2),reserve NUMERIC(14,2),decision JSONB,validation_evidence JSONB,explanation TEXT,payment_receipt TEXT,decision_actor_id BIGINT,payment_actor_id BIGINT,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,created_by BIGINT NOT NULL,approved_by BIGINT,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,claim_ref),UNIQUE(tenant_id,idempotency_key),CHECK(status IN ('fnol','coverage_review','evidence','estimate','reserve_review','decision_review','approved','payment_pending','paid','recovery','disputed','closed')),CHECK(estimate IS NULL OR estimate>=0),CHECK(reserve IS NULL OR reserve>=0));
CREATE TABLE IF NOT EXISTS claim_tasks(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,claim_id BIGINT NOT NULL REFERENCES governed_claims(id),task_type TEXT NOT NULL,assigned_to BIGINT,status TEXT NOT NULL DEFAULT 'open',due_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS claim_recoveries(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,claim_id BIGINT NOT NULL REFERENCES governed_claims(id),recovery_type TEXT NOT NULL,amount NUMERIC(14,2) NOT NULL,status TEXT NOT NULL,external_reference TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(amount>=0));
CREATE TABLE IF NOT EXISTS claim_disputes(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,claim_id BIGINT NOT NULL REFERENCES governed_claims(id),reason TEXT NOT NULL,outcome TEXT,appeal_received_at TIMESTAMPTZ NOT NULL,closed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS claim_integration_runs(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,provider TEXT NOT NULL,operation TEXT NOT NULL,status TEXT NOT NULL,external_reference TEXT,error_code TEXT,error_message TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(status IN ('queued','succeeded','failed','manual_review')));
CREATE TABLE IF NOT EXISTS claim_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,actor_user_id BIGINT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,before_state JSONB,after_state JSONB,request_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
